<?php $available = $product['status_ketersediaan'] === 'tersedia' && (int) $product['stok'] > 0; ?>
<article class="product-card h-100"><a class="product-visual" href="<?= site_url('katalog/' . $product['slug']) ?>" tabindex="-1" aria-hidden="true"><img src="<?= esc(product_image($product['gambar']), 'attr') ?>" alt="<?= esc($product['nama_produk'], 'attr') ?>" width="600" height="680" loading="lazy"><span class="availability"><?= ! $available ? 'Habis' : ((int) $product['stok'] <= 3 ? 'Stok menipis' : 'Tersedia') ?></span></a><div class="product-info"><p class="product-category"><?= esc($product['kategori']) ?></p><h3><a href="<?= site_url('katalog/' . $product['slug']) ?>"><?= esc($product['nama_produk']) ?></a></h3><p class="product-price"><?= rupiah($product['harga']) ?></p><p class="stock-info">Stok: <?= (int) $product['stok'] ?></p><div class="product-actions"><a class="detail-link" href="<?= site_url('katalog/' . $product['slug']) ?>">Lihat Detail <span aria-hidden="true">↗</span></a><?php if ($available): ?><form method="post" action="<?= site_url('keranjang/tambah/' . $product['id']) ?>"><?= csrf_field() ?><input type="hidden" name="return_to" value="katalog"><input type="hidden" name="qty" value="1"><button class="btn btn-sm btn-primary w-100" type="submit">Tambah ke Keranjang</button></form><?php else: ?><button class="btn btn-sm btn-primary w-100" disabled>Stok Habis</button><?php endif ?></div></div></article>
